import React from "react";
import { NavLink, useNavigate } from "react-router-dom";
import Brand from "../ui/Brand";
const links = [{
  to: "/dashboard",
  label: "Overview",
  icon: "▦"
}, {
  to: "/reports",
  label: "Reports queue",
  icon: "▤",
  badge: "12"
}, {
  to: "/analytics",
  label: "Analytics",
  icon: "◷"
}, {
  to: "/officers",
  label: "Officers",
  icon: "♙"
}];
const Sidebar = ({
  open,
  onClose
}) => {
  const navigate = useNavigate();
  return <aside className={`sidebar ${open ? "open" : ""}`}>
      <div className="brand-wrap">
        <Brand />
        <button className="close-menu" onClick={onClose}>
          ×
        </button>
      </div>
      <div className="workspace">
        <span className="workspace-icon">N</span>
        <span>
          <b>NEMA Malawi</b>
          <small>Regional operations</small>
        </span>
        <span className="chev">⌄</span>
      </div>
      <div className="nav-label">WORKSPACE</div>
      <nav>
        {links.map(link => <NavLink key={link.to} to={link.to} className={({
        isActive
      }) => `nav-item ${isActive ? "selected" : ""}`} onClick={onClose}>
            <span className="nav-icon">{link.icon}</span>
            {link.label}
            {link.badge && <span className="nav-badge">{link.badge}</span>}
          </NavLink>)}
      </nav>
      <div className="sidebar-bottom">
        <div className="help-card">
          <span className="help-icon">✳</span>
          <b>Need a hand?</b>
          <p>Visit the operations guide for help with your dashboard.</p>
          <button onClick={() => window.alert("Operations guide coming soon")}>
            Open guide <span>↗</span>
          </button>
        </div>
        <button className="profile" onClick={() => navigate("/login")}>
          <span className="avatar">TK</span>
          <span>
            <b>Thoko Kalua</b>
            <small>Administrator</small>
          </span>
          <span className="more">···</span>
        </button>
      </div>
    </aside>;
};
export default Sidebar;
